import { create } from 'zustand'

// ============================================================================
// Types
// ============================================================================

/** A part from the catalog, ready to be added to cart */
export interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number // in cents (integer)
  quantityOnHand: number
}

/** VAT rate ID constants — matches server vatRates table */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

/** Customer selector item from GET /customers (search response) */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

/** Payload sent to POST /sales for checkout */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

// ============================================================================
// Helpers — Line item math (all amounts in cents, integer)
// ============================================================================

/**
 * Compute line totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 */
function computeLineTotals(
  priceNet: number,
  quantity: number,
  discountPercentBps: number | null,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(priceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return { net: lineNetTotal, vat: lineVatTotal, gross: lineNetTotal + lineVatTotal }
}

// ============================================================================
// Store
// ============================================================================

interface PosCartState {
  // Line items in the cart
  lineItems: CartLineItem[]

  // Selected customer (null = walk-in)
  customerId: string | null

  // Checkout state
  checkoutError: string | null
  checkoutSuccess: CheckoutSuccess | null
  isCheckingOut: boolean

  // Computed totals (derived from line items)
  subtotalNet: number
  vatTotal: number
  totalGross: number

  // Whether the cart can be checked out
  canCheckout: boolean
}

interface PosCartActions {
  // Line item operations
  addLineItem: (part: PartCatalogItem, quantity?: number) => void
  removeLineItem: (partId: string) => void
  updateQuantity: (partId: string, quantity: number) => void
  applyDiscount: (partId: string, discountPercentBps: number) => void
  changeVatRate: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void

  // Customer selection
  setCustomer: (customerId: string | null) => void

  // Checkout state management
  clearCart: () => void
  clearErrors: () => void
  startCheckout: () => void
  finishCheckout: (success: CheckoutSuccess) => void
  failCheckout: (error: string) => void
  setCheckoutError: (error: string | null) => void
  setCheckoutSuccess: (success: CheckoutSuccess | null) => void

  // Get checkout payload for API call
  getCheckoutPayload: () => CheckoutPayload
}

export type PosCartStore = PosCartState & PosCartActions

const initialState: PosCartState = {
  lineItems: [],
  customerId: null,
  checkoutError: null,
  checkoutSuccess: null,
  isCheckingOut: false,
  subtotalNet: 0,
  vatTotal: 0,
  totalGross: 0,
  canCheckout: false,
}

function computeTotals(lineItems: CartLineItem[]): { subtotalNet: number; vatTotal: number; totalGross: number } {
  let subtotalNet = 0
  let vatTotal = 0

  for (const item of lineItems) {
    const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
    const totals = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
    subtotalNet += totals.net
    vatTotal += totals.vat
  }

  return { subtotalNet, vatTotal, totalGross: subtotalNet + vatTotal }
}

/** Compute line-level totals for a single cart item */
function computeItemTotals(item: {
  priceNet: number
  quantity: number
  discountPercent: number | null
  vatRateId: keyof typeof VAT_RATES
}): Pick<CartLineItem, 'lineTotalNet' | 'lineTotalVat' | 'lineTotalGross'> {
  const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
  const { net, vat, gross } = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
  return { lineTotalNet: net, lineTotalVat: vat, lineTotalGross: gross }
}

function updateComputedState(state: PosCartStore): Partial<PosCartState> {
  const totals = computeTotals(state.lineItems)
  return {
    ...totals,
    canCheckout: state.lineItems.length > 0,
  }
}

export const useCartStore = create<PosCartStore>((set, get) => ({
  ...initialState,

  // ── Line Item Operations ────────────────────────────────────────

  addLineItem: (part, quantity = 1) => {
    set((state) => {
      // If quantity is 0 or less, remove existing line item
      if (quantity <= 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== part.id)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      const existingIndex = state.lineItems.findIndex((item) => item.partId === part.id)

      let newItems: CartLineItem[]

      if (existingIndex >= 0) {
        // Increment quantity for existing line item
        const existingItem = state.lineItems[existingIndex]
        const newQty = existingItem.quantity + quantity
        newItems = [...state.lineItems]
        newItems[existingIndex] = {
          ...existingItem,
          quantity: newQty,
          ...computeItemTotals({ priceNet: existingItem.priceNet, quantity: newQty, discountPercent: existingItem.discountPercent, vatRateId: existingItem.vatRateId }),
        }
      } else {
        // Add new line item
        const totals = computeItemTotals({ priceNet: part.priceNet, quantity, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
        const newItem: CartLineItem = {
          partId: part.id,
          barcode: part.barcode,
          name: part.name,
          priceNet: part.priceNet,
          quantity,
          vatRateId: DEFAULT_VAT_RATE,
          discountPercent: null,
          ...totals,
        }
        newItems = [...state.lineItems, newItem]
      }

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  removeLineItem: (partId) => {
    set((state) => {
      const newItems = state.lineItems.filter((item) => item.partId !== partId)
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  updateQuantity: (partId, quantity) => {
    set((state) => {
      // Remove if quantity is exactly 0
      if (quantity === 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== partId)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      // Clamp to minimum of 1 (negative values become 1)
      const clampedQty = Math.max(1, quantity)

      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, quantity: clampedQty, ...computeItemTotals({ ...item, quantity: clampedQty }) }
          : item
      )

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  applyDiscount: (partId, discountPercentBps) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, discountPercent: discountPercentBps, ...computeItemTotals({ ...item, discountPercent: discountPercentBps }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  changeVatRate: (partId, newVatRateId) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, vatRateId: newVatRateId, ...computeItemTotals({ ...item, vatRateId: newVatRateId }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Customer Selection ──────────────────────────────────────────

  setCustomer: (customerId) => {
    set({ customerId })
  },

  // ── Checkout State Management ───────────────────────────────────

  clearCart: () => {
    set({ ...initialState, lineItems: [], customerId: null })
  },

  clearErrors: () => {
    set({ checkoutError: null, checkoutSuccess: null })
  },

  startCheckout: () => {
    set({ isCheckingOut: true, checkoutError: null })
  },

  failCheckout: (error) => {
    set({ isCheckingOut: false, checkoutError: error })
  },

  setCheckoutError: (error) => {
    set({ checkoutError: error })
  },

  setCheckoutSuccess: (success) => {
    set({ checkoutSuccess: success })
  },

  finishCheckout: (success) => {
    set({
      isCheckingOut: false,
      checkoutSuccess: success,
      lineItems: [],
      customerId: null,
      subtotalNet: 0,
      vatTotal: 0,
      totalGross: 0,
      canCheckout: false,
    })
  },

  // ── Checkout Payload Builder ────────────────────────────────────

  getCheckoutPayload: (): CheckoutPayload => {
    const state = get()
    return {
      customerId: state.customerId,
      paymentMethod: 'cash', // default — can be overridden by caller
      lineItems: state.lineItems.map((item) => ({
        partId: item.partId,
        quantity: item.quantity,
        unitPriceNet: item.priceNet,
        vatRateId: item.vatRateId,
        description: item.name,
      })),
    }
  },
}))

import { z } from 'zod'
import { partLineItemVariant, laborLineItemVariant, bicycleLineItemVariant } from './line-item-variants.js'

/** Payment method accepted at checkout */
export const paymentMethodSchema = z.enum(['cash', 'card'])

export type PaymentMethod = z.infer<typeof paymentMethodSchema>

/** A single line item in a sale cart / creation request — discriminated union of part, labor, bicycle */
export const cartLineItemSchema = z.discriminatedUnion('lineType', [
  partLineItemVariant.toSchema(),
  laborLineItemVariant.toSchema(),
  bicycleLineItemVariant.toSchema(),
])

export type CartLineItem = z.infer<typeof cartLineItemSchema>

/** Full input for creating a direct sale at checkout */
export const createDirectSaleInputSchema = z.object({
  /** Optional customer ID — null/absent means walk-in */
  customerId: z.string().nullable().optional(),
  /** Payment method for the full amount */
  paymentMethod: paymentMethodSchema,
  /** Line items being purchased (part, labor, or bicycle) */
  lineItems: z.array(cartLineItemSchema).min(1, 'At least one line item is required'),
})

export type CreateDirectSaleInput = z.infer<typeof createDirectSaleInputSchema>

import { z } from 'zod'

// ---------------------------------------------------------------------------
// Shared Line Item Variant Definitions
//
// Each variant is a composable building block that modules import and use to
// construct their own discriminated union schemas. This eliminates duplication
// of base fields (description, quantity, unitPriceNet, vatRateId, discountPercent)
// across repair, quote, customer-order, and sales validation schemas.
// ---------------------------------------------------------------------------

/** Base fields shared by all line item types */
const baseLineItemFields = {
  description: z.string().min(1, 'description is required').max(500),
  quantity: z.number().int().positive('quantity must be a positive integer'),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  vatRateId: z.string().min(1, 'vatRateId is required'),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(),
}

// ---------------------------------------------------------------------------
// Part Variant
// ---------------------------------------------------------------------------

/**
 * A reusable part line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 */
export const partLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'part' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('part'),
      partId: z.string().min(1, 'partId is required'),
    })
  },
}

/** Input type for a part line item */
export type PartLineItemInput = z.infer<ReturnType<typeof partLineItemVariant.toSchema>>

// ---------------------------------------------------------------------------
// Labor Variant
// ---------------------------------------------------------------------------

/**
 * A reusable labor line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 * All labor-specific fields are nullable — modules may add refinements
 * to enforce stricter requirements (e.g., requiring laborServiceId).
 */
export const laborLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'labor' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('labor'),
      laborServiceId: z.string().nullable().optional(),
      minutesWorked: z.number().int().positive().nullable().optional(),
      hourlyRateSnapshot: z.number().int().nonnegative().nullable().optional(),
    })
  },
}

/** Input type for a labor line item */
export type LaborLineItemInput = z.infer<ReturnType<typeof laborLineItemVariant.toSchema>>

// ---------------------------------------------------------------------------
// Bicycle Variant
// ---------------------------------------------------------------------------

/**
 * A reusable bicycle line item variant definition.
 * Modules compose this into their own discriminated union schemas.
 * All bicycle-specific fields are nullable — modules may add refinements
 * to enforce stricter requirements as needed.
 */
export const bicycleLineItemVariant = {
  /** Discriminator value for the `lineType` field */
  lineType: 'bicycle' as const,

  /** Build a Zod schema object for use in a discriminated union */
  toSchema() {
    return z.object({
      ...baseLineItemFields,
      lineType: z.literal('bicycle'),
      bicycleId: z.string().nullable().optional(),
      bicycleBrand: z.string().max(100).nullable().optional(),
      bicycleModel: z.string().max(200).nullable().optional(),
      bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).nullable().optional(),
      bicycleColor: z.string().max(50).nullable().optional(),
      bicycleFrameSize: z.string().max(20).nullable().optional(),
    })
  },
}

/** Input type for a bicycle line item */
export type BicycleLineItemInput = z.infer<ReturnType<typeof bicycleLineItemVariant.toSchema>>

import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useCartStore, VAT_RATES } from '../store'

// ============================================================================
// Component — Cart Display
// ============================================================================

export function CartDisplay() {
  const lineItems = useCartStore((s) => s.lineItems)
  const subtotalNet = useCartStore((s) => s.subtotalNet)
  const vatTotal = useCartStore((s) => s.vatTotal)
  const totalGross = useCartStore((s) => s.totalGross)
  const updateQuantity = useCartStore((s) => s.updateQuantity)
  const removeLineItem = useCartStore((s) => s.removeLineItem)
  const changeVatRate = useCartStore((s) => s.changeVatRate)

  if (lineItems.length === 0) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="text-center text-muted-foreground py-8">
            Cart is empty — search for parts above to add items
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardContent className="p-0">
        {/* Line items list */}
        <div className="divide-y max-h-[400px] overflow-y-auto">
          {lineItems.map((item) => (
            <CartLineItemRow
              key={item.partId}
              item={item}
              onUpdateQuantity={updateQuantity}
              onVatChange={changeVatRate}
              onRemove={removeLineItem}
            />
          ))}
        </div>

        {/* Running totals */}
        <div className="border-t p-4 space-y-1">
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">Subtotal (net)</span>
            <span className="font-mono">{formatPrice(subtotalNet)}</span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-muted-foreground">VAT</span>
            <span className="font-mono">{formatPrice(vatTotal)}</span>
          </div>
          <div className="flex justify-between font-bold text-base pt-2 border-t">
            <span>Total (gross)</span>
            <span className="font-mono">{formatPrice(totalGross)}</span>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

// ============================================================================
// Sub-component — Single Line Item Row
// ============================================================================

interface CartLineItemRowProps {
  item: ReturnType<typeof useCartStore.getState>['lineItems'][number]
  onUpdateQuantity: (partId: string, quantity: number) => void
  onVatChange: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void
  onRemove: (partId: string) => void
}

function CartLineItemRow({ item, onUpdateQuantity, onVatChange, onRemove }: CartLineItemRowProps) {
  return (
    <div className="p-3 flex items-center gap-3">
      {/* VAT rate selector */}
      <select
        value={item.vatRateId}
        onChange={(e) => onVatChange(item.partId, e.target.value as keyof typeof VAT_RATES)}
        className="h-7 px-1 text-xs border rounded bg-background font-mono shrink-0"
        title="VAT rate"
      >
        <option value="vat-zero">0%</option>
        <option value="vat-reduced">6%</option>
        <option value="vat-standard">21%</option>
      </select>

      {/* Quantity controls */}
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity - 1)}
          className="h-7 w-7 p-0"
        >
          −
        </Button>
        <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onUpdateQuantity(item.partId, item.quantity + 1)}
          className="h-7 w-7 p-0"
        >
          +
        </Button>
      </div>

      {/* Part info */}
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium truncate">{item.name}</div>
        <div className="text-xs text-muted-foreground flex items-center gap-2">
          <span>{formatPrice(item.priceNet)} each × {item.quantity}</span>
          <span className="text-muted-foreground/60">·</span>
          <span className="text-muted-foreground/80 font-mono">
            VAT: {VAT_RATES[item.vatRateId] / 100}%
          </span>
        </div>
      </div>

      {/* Line total */}
      <div className="text-right shrink-0">
        <div className="font-mono text-sm font-medium">{formatPrice(item.lineTotalGross)}</div>
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onRemove(item.partId)}
          className="h-5 px-1 text-xs text-destructive hover:text-destructive"
        >
          ✕
        </Button>
      </div>
    </div>
  )
}

// ============================================================================
// Helpers
// ============================================================================

function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

/**
 * POS feature types — explicit interfaces using shared domain types.
 *
 * This module defines all types used by the POS feature, importing from
 * `shared/types/` as the single source of truth for domain entities.
 */

import type { Product } from '@shared/types/product.js'
import type { Customer } from '@shared/types/customer.js'

// ============================================================================
// Shared Type Aliases — derived from shared types
// ============================================================================

/** Compact catalog item for list/table display and cart operations. */
export interface PartCatalogItem extends Pick<Product, 'id' | 'barcode' | 'name' | 'priceNet' | 'quantityOnHand'> {}

/** Customer selector item for dropdown selectors (compact shape). */
export interface CustomerSelectorItem extends Pick<Customer, 'id' | 'type'> {
  /** Human-readable name: "firstName lastName" for private, companyName for company. */
  displayName: string
}

// ============================================================================
// Cart Types — internal to the POS feature
// ============================================================================

/** VAT rate ID constants — matches server vatRates table. */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts. */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart (with computed totals). */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

// ============================================================================
// Checkout Types — request/response shapes for the checkout flow
// ============================================================================

/** Payload sent to POST /sales for checkout. */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales. */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

import type { CheckoutPayload, CheckoutSuccess } from '../store'

// ============================================================================
// Types — Server response shapes (raw JSON from Hono routes)
// ============================================================================

/** Response shape for a created sale */
export interface SaleResponse {
  /** The created sale header */
  sale: Record<string, unknown>
  /** The payment record for this sale */
  payment: Record<string, unknown>
  /** All line items for this sale */
  lineItems: Record<string, unknown>[]
}

/** Error response from POST /sales */
export interface SaleError {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

// ============================================================================
// Checkout Service — calls POST /api/sales
// ============================================================================

const API_BASE = ''

/**
 * Submit a checkout to the server.
 *
 * Calls `POST /api/sales` with the cart payload and returns the created sale
 * data, or throws on failure.
 *
 * @param payload — Checkout payload from cart store
 * @returns Sale response with sale header, payment, and line items
 */
export async function submitCheckout(payload: CheckoutPayload): Promise<SaleResponse> {
  const response = await fetch(`${API_BASE}/api/sales`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as SaleError
    // Re-throw with the server's error message for display
    throw new Error(errorBody.error ?? `Checkout failed with status ${response.status}`)
  }

  return (await response.json()) as SaleResponse
}

/**
 * Extract sale number and total from a successful checkout response.
 */
export function parseCheckoutSuccess(response: SaleResponse): CheckoutSuccess {
  const sale = response.sale as Record<string, unknown>
  return {
    saleNumber: String(sale.sale_number ?? ''),
    totalGross: Number(sale.total_gross ?? 0),
  }
}

/**
 * Quote feature types — mirrors API response shapes for frontend use.
 */

// ============================================================================
// Quote Status
// ============================================================================

export type QuoteStatus = 'draft' | 'sent' | 'converted' | 'rejected'

/** Color mapping for status badges */
export const QUOTE_STATUS_COLORS: Record<QuoteStatus, string> = {
  draft: 'bg-blue-100 text-blue-800',
  sent: 'bg-yellow-100 text-yellow-800',
  converted: 'bg-green-100 text-green-800',
  rejected: 'bg-red-100 text-red-800',
}

// ============================================================================
// Line Item Type
// ============================================================================

export type QuoteLineItemType = 'part' | 'labor' | 'bicycle'

/** Label for each line item type */
export const LINE_TYPE_LABELS: Record<QuoteLineItemType, string> = {
  part: 'Part',
  labor: 'Labor',
  bicycle: 'Bicycle',
}

// ============================================================================
// Quote Detail Shape (matches API response)
// ============================================================================

export interface QuoteDetail {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
  lineItems: QuoteLineItem[]
  createdAt: number
  updatedAt: number
}

/** Compact quote shape for list display */
export interface QuoteListItem {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
